const aliases={'gardendale-separate-day-school':'riverstone-k-12-school','gardendale':'riverstone-k-12-school','meadowlane-primary-elementary-school':'meadowlane-intermediate-elem','meadowlane-primary-elem':'meadowlane-intermediate-elem'};
function render(s){ s=aliases[s]||s; if(!SHEETS[s])return; stage.innerHTML=SHEETS[s]; if(location.hash.slice(1)!==s) history.replaceState(null,'','#'+s); sel.value=s; if(dailyView)dailyView.show(s); window.scrollTo(0,0); }
sel.addEventListener('change',e=>render(e.target.value));
window.addEventListener('hashchange',()=>render(location.hash.slice(1)));
const fromHash=location.hash.slice(1);
const initial=aliases[fromHash]||fromHash;
render(SHEETS[initial]?initial:sel.value);

/* Shared validation for current-year values in the original profile charts. */
(function (root) {
  'use strict';
  const MAX_AGE = 36 * 60 * 60 * 1000;
  function validate(data, year, now = Date.now()) {
    if (!data || data.contract !== 'bps-school-profile-daily-public' || data.schema_version !== 1 ||
        !data.source || data.source.syear !== year || data.source.school_year !== `${year}-${year + 1}` ||
        !data.source.refresh_id || !data.schools) throw Error('Unexpected daily contract');
    const completed = Date.parse(data.source.refresh_completed_at_utc);
    const generated = Date.parse(data.generated_at);
    const started = Date.parse(data.source.refresh_started_at_utc);
    if (![completed, generated, started].every(Number.isFinite) || started > completed ||
        generated < completed || generated > now + 300000 || completed > now + 300000 ||
        now - completed > MAX_AGE) throw Error('Daily data is stale or has invalid timestamps');
    const count = x => x === null || (Number.isInteger(x) && x >= 0);
    const rate = x => x === null || (Number.isFinite(x) && x >= 0 && x <= 100);
    const profiles=[...Object.entries(data.schools),...(data.district?[['district',data.district]]:[])];
    for (const [code, s] of profiles) {
      if(code!=='district'&&data.school_details_version===1&&!s?.school_details)throw Error('Missing school details');
      if(code!=='district'&&s?.school_details){
        const d=s.school_details;
        for(const k of ['school_name','principal','school_address','school_city','school_zip','school_phone','web_address','school_mission','school_vision','title_1'])
          if(d[k]!==null&&(typeof d[k]!=='string'||d[k].length>12000))throw Error('Invalid school details');
        if(d.title_1!==null&&!['Y','N'].includes(d.title_1))throw Error('Invalid Title I status');
      }
      if ((code!=='district'&&!/^\d{4}$/.test(code)) || !s || !count(s.enrollment_total) || !rate(s.ada_pct) ||
          !s.enrollment_by_grade || !s.demographics || !s.programs || !s.source || !s.status ||
          !Object.values(s.enrollment_by_grade).every(count) ||
          !Object.values(s.demographics).every(count) || !s.lre ||
          s.lre.threshold_operator !== '>' || s.lre.threshold_percent !== 80 ||
          !count(s.lre.count) || !count(s.lre.population) || !rate(s.lre.pct)) throw Error('Invalid daily school');
      for (const p of Object.values(s.programs)) {
        if (!p || !count(p.count) || !rate(p.pct)) throw Error('Invalid daily program');
      }
      if(data.source.race_suppression==='positive_under_10_only'){
        const races=['Asian','Black','Hispanic','White','Other'];
        if(!s.demographics_status || Object.keys(s.demographics).length!==5)throw Error('Invalid race categories');
        for(const race of races){
          const value=s.demographics[race],status=s.demographics_status[race];
          if(status==='suppressed'){if(value!==null)throw Error('Suppressed race count exposed');}
          else if(status!=='available'||!Number.isInteger(value)||value<0||value>s.enrollment_total||(data.source.demographic_suppression!=='none'&&value>0&&value<10))throw Error('Invalid visible race count');
        }
      }
      if (s.ada_by_race) for (const r of Object.values(s.ada_by_race)) {
        if (!r || !count(r.students) || !rate(r.ada_pct)) throw Error('Invalid attendance by race');
      }
    }
    return data;
  }
  const api = {validate};
  if (typeof module !== 'undefined' && module.exports) module.exports = api;
  else root.BpsDaily = api;
})(typeof globalThis !== 'undefined' ? globalThis : this);

/* Updates the existing chart/table bodies. Historical values keep their actual years. */
(function(root){
'use strict';
const RACES=['Asian','Black','Hispanic','White','Other'];
const GRADES=['PK','KG','01','02','03','04','05','06','07','08','09','10','11','12'];
const PROGRAMS=[['General Education [ESE: N]','General'],['Exceptional Student Education','ESE'],['Gifted','Gifted'],['English Language Learners [LY]','ELL']];
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const n=x=>x==null?'—':Number(x).toLocaleString('en-US');
const p=x=>x==null?'—':Number(x).toFixed(1)+'%';
const pct=(a,b)=>a==null||!b?null:100*a/b;
const note=(s,cls='')=>`<div class="note ${cls}">${esc(s)}</div>`;
// Preserve the released categories and source counts. Never pool or backfill missing races.
function demographicRows(s){
  const total=s?.enrollment_total;
  return RACES.map(label=>{
    const value=s?.demographics?.[label];
    const count=Number.isInteger(value)&&value>=0&&Number.isInteger(total)&&value<=total?value:null;
    const suppressed=s?.demographics_status?.[label]==='suppressed';
    return {label,count:suppressed?null:count,percent:suppressed?null:pct(count,total),suppressed};
  });
}
function enrollment(s,h,stamp,year){
  const current=s?.enrollment_by_grade||{};
  const normalize=g=>g.replace('Grade ','').padStart(2,'0');
  const historical=Object.fromEntries(h.grades.map(g=>[normalize(g[0]),g.slice(1)]));
  const grades=GRADES.filter(g=>g in current||g in historical);
  const pair=(a,b)=>`<td>${n(a)}</td><td>${p(b)}</td>`;
  const head=[`${year} – ${year+1}`,`${year-1} – ${year}`,`${year-2} – ${year-1}`].map((y,i)=>
    `<th colspan="2">${y}${i===0?'<br><span class="cap">'+esc(stamp)+'</span>':h.combined?'<br><span class="cap">Intermediate only</span>':''}</th>`).join('');
  let rows='<tr class="totr"><td class="gl">Total Enrollment</td>'+pair(s?.enrollment_total,s?.enrollment_total?100:null)+h.totals.map(t=>pair(t,t?100:null)).join('')+'</tr>';
  for(const g of grades){
    const old=historical[g]||[null,null,null,null];
    const c=s?(g in current?current[g]:0):null;
    rows+='<tr><td class="gl">• Grade '+esc(g)+'</td>'+pair(c,pct(c,s?.enrollment_total))+pair(old[0],old[1])+pair(old[2],old[3])+'</tr>';
  }
  rows+='<tr class="ph"><td class="gl">Programs</td><td colspan="6"></td></tr>';
  for(const [label,key] of PROGRAMS){
    const prior=h.programs.find(v=>v[0]===label),v=s?.programs[key];
    rows+='<tr><td class="gl">'+esc(label)+'</td>'+pair(v?.count,v?.pct)+pair(prior?.[1],prior?.[2])+pair(null,null)+'</tr>';
  }
  return '<table class="en"><thead><tr><th rowspan="2" class="gl lblh">Grade-Level Enrollment</th>'+head+'</tr><tr>'+('<th>Count</th><th>%</th>'.repeat(3))+'</tr></thead><tbody>'+rows+'</tbody></table>';
}
// Geometry and color family retained from the original D2v2 demographics chart.
function demoChart(rows){
  const values=rows.map(r=>r.count),max=Math.max(1,...values.filter(v=>v!==null));
  const ceiling=[50,100,150,200,250,300,400,500,600,750,1000].find(v=>v>=max)||Math.ceil(max/500)*500;
  let svg='<svg role="img" aria-label="Current-year student demographics" viewBox="0 0 340 192" width="100%" height="192">';
  for(const gv of [0,ceiling/2,ceiling]){
    const y=162-gv/ceiling*148;
    svg+=`<line x1="37" y1="${y}" x2="340" y2="${y}" stroke="#cdded7"/><text x="32" y="${y+4}" text-anchor="end" font-size="9.5" fill="#3d4a43">${n(gv)}</text>`;
  }
  rows.forEach((r,i)=>{
    const v=values[i],cx=37+(i+.5)*303/rows.length,height=v===null?0:v/ceiling*148;
    if(v!==null)svg+=`<rect x="${cx-14.4}" y="${162-height}" width="28.8" height="${height}" rx="2.5" fill="#256d2c"/>`;
    const label=esc(r.label);
    svg+=`<text x="${cx}" y="${157-height}" text-anchor="middle" font-size="12.5" font-weight="700" fill="#22302a">${r.suppressed?'*':n(v)}</text><text x="${cx}" y="179" text-anchor="middle" font-size="12" fill="#22302a">${label}</text>`;
  });
  return svg+'</svg>';
}
function parts(s,h,stamp,year=2026){
  const row=(label,a,b,suppressed=false)=>`<tr><td class="l">${esc(label)}</td><td>${suppressed?'*':n(a)}</td><td>${suppressed?'*':p(b)}</td></tr>`;
  const frl=s?.programs.FRL;
  const title1=h.district?(s?.title_i_summary??'—'):({Y:'YES',N:'NO'}[s?.school_details?.title_1]??'—');
  const demographics=demographicRows(s);
  const dm='<table class="kv">'+row('Free/Reduced Lunch (FRL)',frl?.count,frl?.pct)+`<tr><td class="l">Title I Status</td><td colspan="2">${esc(title1)}</td></tr>`+
    '<tr class="sh"><td class="l">Student Demographics</td><td>Count</td><td>Percentage</td></tr>'+row(`${year} – ${year+1} Total Enrollment`,s?.enrollment_total,s?.enrollment_total?100:null)+
    demographics.map(r=>row(r.label,r.count,r.percent,r.suppressed)).join('')+'</table><div class="ct">Student Demographics</div>'+demoChart(demographics)+note(stamp);
  const ar=RACES.map(r=>{const v=s?.ada_by_race?.[r];return row(r,v?.students,v?.ada_pct,v?.status==='suppressed');}).join('');
  const ada=`<div class="adahead"><span class="big">${p(s?.ada_pct)}</span><span class="cap2">${year} – ${year+1} · ${esc(stamp)}</span></div>`+
    '<table class="kv tight"><tr class="sh"><td class="l">By Race</td><td>Students</td><td>Percentage</td></tr>'+ar+'</table>';
  const lr=s?.lre;
  const lre='<table class="kv tight"><tr class="sh"><td class="l">'+year+' – '+(year+1)+'</td><td>Count</td><td>Percentage</td></tr>'+row('Time with nondisabled peers >80%',lr?.count,lr?.pct)+'</table>'+note(stamp);
  const result={enrollment:enrollment(s,h,stamp,year),demographics:dm,attendance:ada,lre};
  if(!h.district)result.identity=identity(s);
  return result;
}
function identity(s){
  const d=s?.school_details||{};
  const row=(label,value)=>`<div class="kvi"><span class="k">${label}</span><span class="v sm">${value||'—'}</span></div>`;
  const address=[d.school_address,[d.school_city,d.school_zip].filter(Boolean).join(', ')].filter(Boolean).map(esc).join('<br>');
  const website=d.web_address&&/^https?:\/\//i.test(d.web_address)?`<a href="${esc(d.web_address)}" target="_blank" rel="noopener">${esc(d.web_address)}</a>`:'—';
  return row('Address',address)+row('Phone',esc(d.school_phone))+row('Principal',esc(d.principal))+
    row('Mission',esc(d.school_mission))+row('Vision',esc(d.school_vision))+
    row('Grade Levels',s?esc(GRADES.filter(g=>g in s.enrollment_by_grade).join(', ')):'—')+
    row('Title I',({Y:'Yes',N:'No'}[d.title_1]||'—'))+row('Website',website);
}
function attach({stage,codes,history,url,year}){
  let data=null,selected=null,message='Loading current-year data…';
  function show(slug){
    selected=slug;if(!codes[slug]&&slug!=='district')return;
    let s=null;
    try{if(data){const valid=root.BpsDaily.validate(data,year);s=slug==='district'?valid.district:valid.schools[codes[slug]];}}
    catch(_){data=null;message='Last pull is out of date. Current-year data needs a successful refresh.';}
    const stamp=s?'As of '+String(s.source.current_as_of).slice(0,10):message;
    if(slug!=='district'){
      const heading=stage.querySelector('.htext h1');
      if(heading)heading.textContent=s?.school_details?.school_name||'School Data Profile';
      const option=root.document?.querySelector(`#schoolsel option[value="${slug}"]`);
      if(option&&s?.school_details?.school_name)option.textContent=s.school_details.school_name;
    }
    for(const [name,html] of Object.entries(parts(s,history[slug],stamp,year))){
      const node=stage.querySelector(`[data-profile-part="${name}"]`);if(node)node.innerHTML=html;
    }
  }
  async function refresh(){
    const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),15000);
    try{
      const response=await fetch(url,{cache:'no-store',credentials:'omit',signal:controller.signal});
      if(!response.ok)throw Error('Daily endpoint unavailable');
      const candidate=root.BpsDaily.validate(await response.json(),year);
      if(Object.values(codes).some(c=>!candidate.schools[c]))throw Error('School missing from Fabric feed');
      data=candidate;
      for(const [slug,code] of Object.entries(codes)){
        const option=root.document?.querySelector(`#schoolsel option[value="${slug}"]`);
        if(option&&candidate.schools[code].school_details?.school_name)option.textContent=candidate.schools[code].school_details.school_name;
      }
    }catch(_){data=null;message='Current-year pull could not be verified. Data refresh needs attention.';}
    finally{clearTimeout(timeout);if(selected)show(selected);}
  }
  refresh();setInterval(refresh,300000);setInterval(()=>{if(selected)show(selected);},60000);return {show};
}
const api={parts,attach,demographicRows,identity};
if(typeof module!=='undefined'&&module.exports)module.exports=api;else root.BpsCharts=api;
})(typeof globalThis!=='undefined'?globalThis:this);

